pub fn collect_func_call_edges(
    items: Rc<Vec<Rc<Node>>>,
    local_func_set: Rc<HashMap<String, bool>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Vec<Rc<CallEdge>>> {
    Rc::new({
        let mut __result = Vec::new();
        for item in items.iter().cloned() {
            __result.extend(
                (*if (((item.params.clone().len() as i64) > 0)
                    && (item.body.clone() != std::option::Option::None))
                {
                    collect_calls_in_expr(
                        crate::v1_std_core::authored_name_at(source_indices.clone(), item.clone()),
                        item.body.clone().clone().unwrap(),
                        local_func_set.clone(),
                        source_indices.clone(),
                    )
                } else {
                    Rc::new(vec![])
                })
                .iter()
                .cloned(),
            );
        }
        __result
    })
}

pub fn collect_calls_in_expr(
    caller: String,
    texpr: Rc<Node>,
    local_func_set: Rc<HashMap<String, bool>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Vec<Rc<CallEdge>>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        let this_edges = match (*texpr.expr_data.clone()).clone() {
            ExprData::ExprCall { .. } => {
                let f =
                    crate::v1_std_core::expr_call_func_at(texpr.clone(), source_indices.clone());
                if crate::v1_compiler_infer_types::emit_map_has(local_func_set.clone(), f.clone()) {
                    Rc::new(vec![Rc::new(CallEdge {
                        caller: caller.clone(),
                        callee: f.clone(),
                    })])
                } else {
                    Rc::new(vec![])
                }
            }
            _ => Rc::new(vec![]),
        };
        let child_edges = Rc::new({
            let mut __result = Vec::new();
            for child in texpr.children.clone().iter().cloned() {
                __result.extend(
                    (*collect_calls_in_expr(
                        caller.clone(),
                        child.clone(),
                        local_func_set.clone(),
                        source_indices.clone(),
                    ))
                    .iter()
                    .cloned(),
                );
            }
            __result
        });
        let result = v1_rt::concat(this_edges.clone(), child_edges.clone());
        result
    })
}

pub fn func_reaches_self(
    root: String,
    current: String,
    call_edges: Rc<Vec<Rc<CallEdge>>>,
    visited: Rc<HashMap<String, bool>>,
) -> bool {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        if crate::v1_compiler_infer_types::emit_map_has(visited.clone(), current.clone()) {
            false
        } else {
            {
                let next_visited = v1_rt::rc_map_insert(visited.clone(), current.clone(), true);
                let callees = Rc::new({
                    let mut __result = Vec::new();
                    for e in Rc::new({
                        let mut __result = Vec::new();
                        for e in call_edges.iter().cloned() {
                            if (e.caller.clone() == current.clone()) {
                                __result.push(e);
                            }
                        }
                        __result
                    })
                    .iter()
                    .cloned()
                    {
                        __result.push(e.callee.clone());
                    }
                    __result
                });
                {
                    let mut __found = false;
                    for c in callees.iter().cloned() {
                        if if (c.clone() == root.clone()) {
                            true
                        } else {
                            func_reaches_self(
                                root.clone(),
                                c.clone(),
                                call_edges.clone(),
                                next_visited.clone(),
                            )
                        } {
                            __found = true;
                            break;
                        }
                    }
                    __found
                }
            }
        }
    })
}

